-- Stale sweep batch 2: 3 feeds fixed, 4 publishers unavailable, 20 undated 2022 Liberte-Algerie articles deleted (data only). Generated by Build-Sql.py. Reverse: reverse.sql.
\set ON_ERROR_STOP on
SET lock_timeout = '5s';
BEGIN;
SELECT 'before|' || p.id || '|' || p.feed_status || '|' || coalesce(f.feed_url, '-') FROM publishers p LEFT JOIN feeds f ON f.publisher_id = p.id AND f.enabled WHERE p.id IN (230, 1052, 301, 2078, 169, 298, 254) ORDER BY p.id;
DO $do$
DECLARE k int;
BEGIN
  UPDATE feeds SET feed_url = 'https://www.radiookapi.net/feed/', etag = NULL, last_modified = NULL
   WHERE publisher_id = 230 AND feed_url = 'https://www.radiookapi.net/rss.xml' AND feed_type = 'rss' AND enabled;
  GET DIAGNOSTICS k = ROW_COUNT; IF k <> 1 THEN RAISE EXCEPTION '230: % feed rows at the old URL, expected 1 - nothing changed', k; END IF;
  UPDATE feeds SET feed_url = 'https://sana.sy/en/feed/?src=ndp', etag = NULL, last_modified = NULL
   WHERE publisher_id = 1052 AND feed_url = 'https://sana.sy/en/?feed=rss2' AND feed_type = 'rss' AND enabled;
  GET DIAGNOSTICS k = ROW_COUNT; IF k <> 1 THEN RAISE EXCEPTION '1052: % feed rows at the old URL, expected 1 - nothing changed', k; END IF;
  UPDATE feeds SET feed_url = 'https://www.lemauricien.com/feed/?src=ndp', etag = NULL, last_modified = NULL
   WHERE publisher_id = 301 AND feed_url = 'https://www.lemauricien.com/feed' AND feed_type = 'rss' AND enabled;
  GET DIAGNOSTICS k = ROW_COUNT; IF k <> 1 THEN RAISE EXCEPTION '301: % feed rows at the old URL, expected 1 - nothing changed', k; END IF;
  DELETE FROM articles WHERE publisher_id = 169 AND published_at IS NULL AND original_url LIKE 'https://www.liberte-algerie.com/%'
   AND fetched_at < DATE '2026-07-27';
  GET DIAGNOSTICS k = ROW_COUNT; IF k <> 20 THEN RAISE EXCEPTION 'Liberte-Algerie: % undated articles, expected 20 - nothing changed', k; END IF;
  IF EXISTS (SELECT 1 FROM articles WHERE publisher_id = 169) THEN RAISE EXCEPTION 'Liberte-Algerie has other articles - nothing changed'; END IF;
  UPDATE publishers SET feed_status = 'unavailable' WHERE id = 2078 AND name = $$RMI Government$$ AND feed_status = 'active';
  GET DIAGNOSTICS k = ROW_COUNT; IF k <> 1 THEN RAISE EXCEPTION '2078: not the active RMI Government - nothing changed'; END IF;
  UPDATE publishers SET feed_status = 'unavailable' WHERE id = 169 AND name = $$Liberté-Algérie$$ AND feed_status = 'active';
  GET DIAGNOSTICS k = ROW_COUNT; IF k <> 1 THEN RAISE EXCEPTION '169: not the active Liberté-Algérie - nothing changed'; END IF;
  UPDATE publishers SET feed_status = 'unavailable' WHERE id = 298 AND name = $$MadaGate$$ AND feed_status = 'active';
  GET DIAGNOSTICS k = ROW_COUNT; IF k <> 1 THEN RAISE EXCEPTION '298: not the active MadaGate - nothing changed'; END IF;
  UPDATE publishers SET feed_status = 'unavailable' WHERE id = 254 AND name = $$Madote$$ AND feed_status = 'active';
  GET DIAGNOSTICS k = ROW_COUNT; IF k <> 1 THEN RAISE EXCEPTION '254: not the active Madote - nothing changed'; END IF;
END $do$;
SELECT 'after|' || p.id || '|' || p.feed_status || '|' || coalesce(f.feed_url, '-') || '|' || (SELECT count(*) FROM articles a WHERE a.publisher_id = p.id AND p.id = 169) FROM publishers p LEFT JOIN feeds f ON f.publisher_id = p.id AND f.enabled WHERE p.id IN (230, 1052, 301, 2078, 169, 298, 254) ORDER BY p.id;
COMMIT;
